import sys

def main():
    import sys
    import math

    def count_valid_subsequences(n, d):
        # Calculate the number of valid subsequences
        # For each element, we can choose to include it or not
        # Total subsequences = 2^n - 1 (all non-empty subsequences)
        # Valid subsequences are those where max - min < d
        # We can use a geometric progression to count these
        if d == 0:
            return 2**n - 1
        else:
            return sum(2**(n-i-1) for i in range(n) if (i+1)*d < 2**n)

    def find_array(X, d):
        # Binary search to find the minimum n such that count_valid_subsequences(n, d) >= X
        low, high = 1, 10000
        while low < high:
            mid = (low + high) // 2
            if count_valid_subsequences(mid, d) < X:
                low = mid + 1
            else:
                high = mid

        if count_valid_subsequences(low, d) < X:
            return -1

        # Construct the array
        array = []
        current_value = 1
        for i in range(low):
            array.append(current_value)
            current_value += d

        return array

    X, d = map(int, sys.stdin.read().split())

    result = find_array(X, d)

    if result == -1:
        print(-1)
    else:
        print(len(result))
        print(' '.join(map(str, result)))

